8	struct NinebotRecordingView: View {
9	    @ObservedObject var model: NinebotViewModel
10	    @StateObject private var recorder = NinebotRideRecorder()
11	    @State private var pendingRecord: NinebotRecordedRide?
12	
13	    private var snapshot: NinebotVehicleSnapshot? {
14	        model.dashboard.primaryVehicle
15	    }
16	
17	    var body: some View {
18	        ZStack {
19	            RecordingBackground()
20	                .ignoresSafeArea()
21	
22	            ScrollView {
23	                VStack(spacing: 18) {
24	                    RecordingHeader(snapshot: snapshot, recorder: recorder)
25	                        .padding(16)
26	                        .ninePlusCard(cornerRadius: 28)
27	
28	                    RecordingSpeedGauge(
29	                        speedKmh: recorder.currentSpeedKmh,
30	                        maxSpeedKmh: recorder.maxSpeedKmh,
31	                        accelerationG: recorder.currentAccelerationG,
32	                        gpsQuality: recorder.gpsQuality,
33	                        isRecording: recorder.isRecording
34	                    )
35	                    .padding(.horizontal, 12)
36	                    .padding(.vertical, 14)
37	                    .ninePlusCard(cornerRadius: 30)
38	
39	                    RecordingControlPanel(
40	                        recorder: recorder,
41	                        canRecord: snapshot != nil,
42	                        onStart: {
43	                            recorder.start(vehicleSN: snapshot?.vehicle.sn)
44	                        },
45	                        onStop: {
46	                            guard let record = recorder.stop() else { return }
47	                            model.saveRecordedRide(record)
48	                            pendingRecord = record
49	                        }
50	                    )
51	
52	                    RecordingMetricsGrid(recorder: recorder)
53	
54	                    RecordingTrackPreview(
55	                        points: recorder.points,
56	                        currentPoint: recorder.currentLocationPoint
57	                    )
58	
59	                    RecordingHistorySection(
60	                        records: model.recordedRides(for: snapshot?.vehicle.sn),
61	                        onDelete: { record in
62	                            model.deleteRecordedRide(id: record.id)
63	                        }
64	                    )
65	                }
66	                .padding(16)
67	                .padding(.bottom, 20)
68	            }
69	        }
70	        .navigationTitle("记录")
71	        .navigationBarTitleDisplayMode(.inline)
72	        .toolbarBackground(.hidden, for: .navigationBar)
73	        .sheet(item: $pendingRecord) { record in
74	            RideAssociationSheet(snapshot: snapshot, record: record) { rideID in
75	                var savedRecord = record
76	                savedRecord.vehicleSN = snapshot?.vehicle.sn
77	                savedRecord.associatedRideID = rideID
78	                model.saveRecordedRide(savedRecord)
79	                pendingRecord = nil
80	            }
81	        }
82	        .onAppear {
83	            recorder.startPreview()
84	        }
85	        .onDisappear {
86	            recorder.stopPreviewIfIdle()
87	        }
88	    }
89	}
