91	extension RecordingGPSQuality {
92	    var title: String {
93	        switch self {
94	        case .waiting: return "等待 GPS"
95	        case .stabilizing: return "校准中"
96	        case .good: return "GPS 稳定"
97	        case .weak: return "GPS 弱"
98	        case .unavailable: return "定位不可用"
99	        }
100	    }
101	
102	    var systemImage: String {
103	        switch self {
104	        case .waiting: return "location"
105	        case .stabilizing: return "scope"
106	        case .good: return "location.fill"
107	        case .weak: return "location.slash"
108	        case .unavailable: return "exclamationmark.triangle.fill"
109	        }
110	    }
111	
112	    var tint: Color {
113	        switch self {
114	        case .waiting, .stabilizing: return Color.teslaSecondaryText
115	        case .good: return Color.teslaGreen
116	        case .weak: return .orange
117	        case .unavailable: return .red
118	        }
119	    }
120	}
