166	    private var statusText: String {
167	        if let error = recorder.lastErrorText {
168	            return error
169	        }
170	        if recorder.isRecording {
171	            // Recording survives backgrounding and lock now, but nothing else
172	            // on screen says so.
173	            return "正在记录 · 可以锁屏，后台继续"
174	        }
175	        if recorder.authorizationStatus == .notDetermined {
176	            return "允许定位后会显示实时位置"
177	        }
178	        if !recorder.isAuthorized {
179	            return "需要在系统设置里允许定位"
180	        }
181	        return "当前位置实时显示，点击开始记录"
182	    }
183	
184	    private var statusColor: Color {
185	        recorder.lastErrorText == nil ? Color.teslaSecondaryText : .orange
186	    }
187	}
