189	private struct RecordingSpeedGauge: View {
190	    var speedKmh: Double
191	    var maxSpeedKmh: Double
192	    var accelerationG: Double
193	    var gpsQuality: RecordingGPSQuality
194	    var isRecording: Bool
195	
196	    private let maxGaugeSpeed = 132.0
197	
198	    var body: some View {
199	        ZStack {
200	            ForEach(0..<33, id: \.self) { index in
201	                Capsule()
202	                    .fill(index % 4 == 0 ? Color.teslaSecondaryText.opacity(0.74) : Color.teslaSecondaryText.opacity(0.28))
203	                    .frame(width: index % 4 == 0 ? 3 : 2, height: index % 4 == 0 ? 18 : 10)
204	                    .offset(y: -128)
205	                    .rotationEffect(.degrees(Double(index) / 32 * 270 - 135))
206	            }
207	
208	            Circle()
209	                .trim(from: 0.125, to: 0.875)
210	                .stroke(Color.teslaControlBackground, style: StrokeStyle(lineWidth: 18, lineCap: .round))
211	                .rotationEffect(.degrees(90))
212	
213	            Circle()
214	                .trim(from: 0.125, to: 0.125 + min(max(speedKmh / maxGaugeSpeed, 0), 1) * 0.75)
215	                .stroke(
216	                    LinearGradient(
217	                        colors: [Color.teslaGreen, .yellow, .red],
218	                        startPoint: .leading,
219	                        endPoint: .trailing
220	                    ),
221	                    style: StrokeStyle(lineWidth: 18, lineCap: .round)
222	                )
223	                .rotationEffect(.degrees(90))
224	                .shadow(color: Color.teslaGreen.opacity(isRecording ? 0.55 : 0.18), radius: isRecording ? 18 : 6)
225	
226	            VStack(spacing: 6) {
227	                Text(formatRecordingSpeed(speedKmh, showsUnit: false))
228	                    .font(.system(size: 72, weight: .bold, design: .rounded))
229	                    .monospacedDigit()
230	                    .foregroundStyle(Color.teslaPrimaryText)
231	                    .lineLimit(1)
232	                    .minimumScaleFactor(0.58)
233	
234	                Text("km/h")
235	                    .font(.headline.monospacedDigit().weight(.semibold))
236	                    .foregroundStyle(Color.teslaSecondaryText)
237	
238	                HStack(spacing: 6) {
239	                    Image(systemName: "arrow.up.forward")
240	                    Text("MAX \(formatRecordingSpeed(maxSpeedKmh))")
241	                }
242	                .font(.caption.monospacedDigit().weight(.bold))
243	                .foregroundStyle(Color.teslaGreen)
244	                .padding(.top, 8)
245	
246	                HStack(spacing: 8) {
247	                    RecordingGaugePill(
248	                        title: gpsQuality.title,
249	                        systemImage: gpsQuality.systemImage,
250	                        tint: gpsQuality.tint
251	                    )
252	                    RecordingGaugePill(
253	                        title: formatRecordingG(accelerationG),
254	                        systemImage: "bolt.circle.fill",
255	                        tint: accelerationG > 0.35 ? .orange : Color.teslaSecondaryText
256	                    )
257	                }
258	                .padding(.top, 4)
259	            }
260	        }
261	        .frame(height: 300)
262	        .frame(maxWidth: .infinity)
263	        .padding(.vertical, 8)
264	    }
265	}
