369	private struct RecordingTrackPreview: View {
370	    var points: [NinebotRideTrackPoint]
371	    var currentPoint: NinebotRideTrackPoint?
372	    @State private var cameraPosition: MapCameraPosition = .automatic
373	
374	    var body: some View {
375	        VStack(alignment: .leading, spacing: 10) {
376	            HStack {
377	                Text("实时轨迹")
378	                    .font(.headline)
379	                    .foregroundStyle(Color.teslaPrimaryText)
380	                Spacer()
381	                Text("\(points.count) 点")
382	                    .font(.caption.monospacedDigit().weight(.semibold))
383	                    .foregroundStyle(Color.teslaSecondaryText)
384	            }
385	
386	            ZStack {
387	                Map(position: $cameraPosition, interactionModes: []) {
388	                    if coordinates.count > 1 {
389	                        MapPolyline(coordinates: coordinates)
390	                            .stroke(Color.teslaGreen, lineWidth: 4)
391	                    }
392	
393	                    ForEach(Array(sampledCoordinates.enumerated()), id: \.offset) { _, coordinate in
394	                        Annotation("轨迹点", coordinate: coordinate) {
395	                            Circle()
396	                                .fill(Color.teslaGreen)
397	                                .frame(width: 5, height: 5)
398	                                .overlay {
399	                                    Circle()
400	                                        .stroke(Color(.systemBackground), lineWidth: 1)
401	                                }
402	                        }
403	                    }
404	
405	                    if let last = displayCoordinates.last {
406	                        Marker("当前位置", systemImage: "location.fill", coordinate: last)
407	                            .tint(Color.teslaGreen)
408	                    }
409	                }
410	                .onChange(of: points.count) { _, _ in
411	                    followCurrentLocation()
412	                }
413	                .onChange(of: currentPoint?.id) { _, _ in
414	                    followCurrentLocation()
415	                }
416	                .onAppear {
417	                    followCurrentLocation()
418	                }
419	
420	                if displayCoordinates.isEmpty {
421	                    VStack(spacing: 8) {
422	                        Image(systemName: "location.viewfinder")
423	                            .font(.title2.weight(.semibold))
424	                        Text("正在获取当前位置")
425	                            .font(.subheadline.weight(.medium))
426	                    }
427	                    .foregroundStyle(Color.teslaSecondaryText)
428	                    .padding(18)
429	                    .background(Color.teslaCardBackground.opacity(0.88))
430	                    .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
431	                }
432	            }
433	            .frame(height: 220)
434	            .clipShape(RoundedRectangle(cornerRadius: 20, style: .continuous))
435	        }
436	        .padding(14)
437	        .ninePlusCard(cornerRadius: 24)
438	    }
439	
440	    private var coordinates: [CLLocationCoordinate2D] {
441	        points.map {
442	            recordingMapCoordinate(latitude: $0.latitude, longitude: $0.longitude)
443	        }
444	    }
445	
446	    private var sampledCoordinates: [CLLocationCoordinate2D] {
447	        sampledMapCoordinates(coordinates)
448	    }
449	
450	    private var currentCoordinate: CLLocationCoordinate2D? {
451	        currentPoint.map {
452	            recordingMapCoordinate(latitude: $0.latitude, longitude: $0.longitude)
453	        }
454	    }
455	
456	    private var displayCoordinates: [CLLocationCoordinate2D] {
457	        if !coordinates.isEmpty {
458	            return coordinates
459	        }
460	        return currentCoordinate.map { [$0] } ?? []
461	    }
462	
463	    private func followCurrentLocation() {
464	        guard let current = displayCoordinates.last else {
465	            cameraPosition = .automatic
466	            return
467	        }
468	
469	        cameraPosition = .region(
470	            MKCoordinateRegion(
471	                center: current,
472	                span: MKCoordinateSpan(latitudeDelta: 0.003, longitudeDelta: 0.003)
473	            )
474	        )
475	    }
476	}
