550	private struct RecordedRideDetailView: View {
551	    var record: NinebotRecordedRide
552	    var onDelete: (NinebotRecordedRide) -> Void
553	    @Environment(\.dismiss) private var dismiss
554	    @State private var isConfirmingDeletion = false
555	    @State private var copiedMessage: String?
556	    @State private var loadedRecord: NinebotRecordedRide?
557	
558	    // List rows carry summaries only; the track is read from disk on open.
559	    private var detailRecord: NinebotRecordedRide {
560	        loadedRecord ?? record
561	    }
562	
563	    var body: some View {
564	        ScrollView {
565	            VStack(alignment: .leading, spacing: 16) {
566	                RecordedRideDetailHero(record: detailRecord)
567	                RecordedRideTrackMap(record: detailRecord)
568	                    .id(detailRecord.points.count)
569	                RecordedRideDetailMetrics(record: detailRecord)
570	                RecordedRideExportCard(record: detailRecord, copiedMessage: $copiedMessage)
571	
572	                if let associatedRideID = record.associatedRideID {
573	                    VStack(alignment: .leading, spacing: 8) {
574	                        Label("已关联接口行程", systemImage: "link")
575	                            .font(.headline)
576	                            .foregroundStyle(Color.teslaPrimaryText)
577	                        Text(associatedRideID)
578	                            .font(.caption.monospaced())
579	                            .foregroundStyle(Color.teslaSecondaryText)
580	                            .textSelection(.enabled)
581	                    }
582	                    .padding(14)
583	                    .frame(maxWidth: .infinity, alignment: .leading)
584	                    .background(Color.teslaCardBackground)
585	                    .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
586	                    .overlay {
587	                        RoundedRectangle(cornerRadius: 18, style: .continuous)
588	                            .stroke(Color.teslaHairline, lineWidth: 1)
589	                    }
590	                }
591	
592	                Button(role: .destructive) {
593	                    isConfirmingDeletion = true
594	                } label: {
595	                    Label("删除这条记录", systemImage: "trash.fill")
596	                        .font(.headline.weight(.semibold))
597	                        .foregroundStyle(.white)
598	                        .frame(maxWidth: .infinity)
599	                        .frame(height: 54)
600	                        .background(Color.red)
601	                        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
602	                }
603	                .buttonStyle(.plain)
604	            }
605	            .padding(16)
606	            .padding(.bottom, 20)
607	        }
608	        .background(Color.teslaPageBackground.ignoresSafeArea())
609	        .navigationTitle("记录详情")
610	        .navigationBarTitleDisplayMode(.inline)
611	        .task(id: record.id) {
612	            guard !record.isTrackLoaded else { return }
613	            loadedRecord = NinebotSharedStore().loadRecordedRide(id: record.id)
614	        }
615	        .overlay(alignment: .top) {
616	            if let copiedMessage {
617	                Text(copiedMessage)
618	                    .font(.footnote.weight(.semibold))
619	                    .foregroundStyle(Color.teslaPrimaryText)
620	                    .padding(.horizontal, 14)
621	                    .padding(.vertical, 9)
622	                    .background(.regularMaterial)
623	                    .clipShape(Capsule())
624	                    .padding(.top, 8)
625	                    .transition(.move(edge: .top).combined(with: .opacity))
626	            }
627	        }
628	        .animation(.easeInOut(duration: 0.18), value: copiedMessage)
629	        .confirmationDialog("删除这条记录？", isPresented: $isConfirmingDeletion, titleVisibility: .visible) {
630	            Button("删除记录", role: .destructive) {
631	                onDelete(record)
632	                dismiss()
633	            }
634	            Button("取消", role: .cancel) {}
635	        } message: {
636	            Text("\(formatRecordingDate(record.startedAt)) · \(formatRecordingDistance(record.distanceKilometers))")
637	        }
638	    }
639	}
